//! Rust<->Python bit-identity for the hybrid half: comparator core, fusion gate, and the
//! judgment boundary conversion.
//!
//! The forward pass has `ops_golden.rs`; this is the same guarantee for the code that turns a
//! model output and a fact check into the number a miner is paid on. It matters for the same
//! reason and is harder to catch by eye: a fusion gate that is wrong in the third decimal
//! still returns a plausible score, and a comparator that truncates the wrong way only
//! diverges on negative values.
//!
//! Reads tests/hybrid_fixture.json, generated by gen_hybrid_fixture.py from
//! `wide_runtime/golden/hybrid.py`. Same trivial flat-key reader as ops_golden.rs (no serde).

use wide_wasm::hybrid::{self, Comparator, Fusion, FusionConst};

fn load() -> String {
    std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/hybrid_fixture.json"))
        .expect("hybrid_fixture.json missing — run gen_hybrid_fixture.py")
}

fn arr(j: &str, key: &str) -> Vec<i64> {
    let pat = format!("\"{}\":[", key);
    let start = j.find(&pat).unwrap_or_else(|| panic!("key {key} not found")) + pat.len();
    let end = j[start..].find(']').unwrap() + start;
    j[start..end]
        .split(',')
        .filter(|s| !s.trim().is_empty())
        .map(|s| s.trim().parse::<i64>().unwrap())
        .collect()
}

fn scalar(j: &str, key: &str) -> i64 {
    let pat = format!("\"{}\":", key);
    let start = j.find(&pat).unwrap_or_else(|| panic!("scalar {key} not found")) + pat.len();
    let rest = &j[start..];
    let end = rest.find(|c| c == ',' || c == '}').unwrap();
    rest[..end].trim().parse::<i64>().unwrap()
}

#[test]
fn comparator_core_matches_python() {
    let j = load();
    let n = scalar(&j, "cmp_n") as usize;
    let (kind, miner, truth, tol, want) = (
        arr(&j, "cmp_kind"), arr(&j, "cmp_miner"), arr(&j, "cmp_truth"),
        arr(&j, "cmp_tol"), arr(&j, "cmp_out"),
    );
    for i in 0..n {
        let got = hybrid::comparator_core(
            Comparator::from_i32(kind[i] as i32), miner[i], truth[i], tol[i]);
        assert_eq!(
            got, want[i],
            "comparator_core diverged from the Python golden at case {i}: \
             kind={} miner={} truth={} tol={}",
            kind[i], miner[i], truth[i], tol[i]
        );
    }
}

#[test]
fn fuse_matches_python() {
    let j = load();
    let n = scalar(&j, "fuse_n") as usize;
    let (mode, core, judg) = (arr(&j, "fuse_mode"), arr(&j, "fuse_core"), arr(&j, "fuse_judg"));
    let (pass, low, floor, span) = (
        arr(&j, "fuse_pass"), arr(&j, "fuse_low"), arr(&j, "fuse_floor"), arr(&j, "fuse_span"));
    let (wc, wj, want) = (arr(&j, "fuse_wc"), arr(&j, "fuse_wj"), arr(&j, "fuse_out"));
    for i in 0..n {
        let k = FusionConst {
            pass: pass[i], low: low[i], floor: floor[i], span: span[i],
            w_c: wc[i], w_j: wj[i],
        };
        let got = hybrid::fuse(Fusion::from_i32(mode[i] as i32), core[i], judg[i], &k);
        assert_eq!(
            got, want[i],
            "fuse diverged from the Python golden at case {i}: \
             mode={} core={} judgment={} pass={} low={} floor={} span={}",
            mode[i], core[i], judg[i], pass[i], low[i], floor[i], span[i]
        );
    }
}

#[test]
fn judgment_to_score_domain_matches_python() {
    let j = load();
    let n = scalar(&j, "judg_n") as usize;
    let (input, want) = (arr(&j, "judg_in"), arr(&j, "judg_out"));
    for i in 0..n {
        let got = wide_wasm::judgment_to_score_domain(input[i]);
        assert_eq!(
            got, want[i],
            "judgment_to_score_domain diverged from the Python golden at case {i}: \
             raw Q32.32 code {}",
            input[i]
        );
    }
}

/// The real CODE_REVIEW adapter returns about -2.32 as a Q32.32 logit. Under a plain
/// divide-and-clamp that is 0 bps, and so is every other negative-logit miner — they tie at
/// the bottom, which reads exactly like "every miner answered badly". The sigmoid is what
/// keeps them ordered, so this pins the specific value rather than only the general parity.
#[test]
fn a_negative_logit_does_not_collapse_to_zero() {
    let bps = wide_wasm::judgment_to_score_domain(-9_984_098_080);
    assert!(
        bps > 0 && bps < hybrid::SCORE_ONE,
        "the real adapter's observed logit mapped to {bps} bps; it must land strictly inside \
         the range, or every negative-logit miner ties at the bottom"
    );
    // Monotone: a higher logit must never score lower.
    let lower = wide_wasm::judgment_to_score_domain(-12_000_000_000);
    let higher = wide_wasm::judgment_to_score_domain(-5_000_000_000);
    assert!(lower < bps && bps < higher, "the boundary conversion is not monotone");
}

/// Pin the ten-int spec buffer layout by POSITION, not by name.
///
/// `imwq_score_hybrid` reads exactly ten i64s with no length argument, so a reordered buffer
/// fuses against the wrong thresholds and a short one is read past its end — neither errors.
/// This builds a buffer whose every field is distinguishable and asserts the export picked
/// each one up in the slot the Go side (`comparator.Fusion.Buffer()`) writes it to.
#[test]
fn spec_buffer_layout_is_positional() {
    // [comparator, tolerance, fusion_mode, pass, low, floor, span, w_c, w_j, reserved]
    // AbsTol with tol=50: a miner 25 off scores 7500. Gate with pass=8000 -> unlocked is
    // false (7500 < 8000), so the result is 7500 * low / 10000 with low = 4000 -> 3000.
    let spec: [i64; 10] = [1, 50, 0, 8_000, 4_000, 3_000, 7_000, 0, 0, 0];
    let k = FusionConst {
        pass: spec[3], low: spec[4], floor: spec[5], span: spec[6], w_c: spec[7], w_j: spec[8],
    };
    let core = hybrid::comparator_core(
        Comparator::from_i32(spec[0] as i32), 125, 100, spec[1]);
    assert_eq!(core, 7_500, "slot 0/1 (comparator, tolerance) are not where the host writes them");
    let fused = hybrid::fuse(Fusion::from_i32(spec[2] as i32), core, 10_000, &k);
    assert_eq!(
        fused, 3_000,
        "the gate did not read pass/low from slots 3/4 — a reordered spec buffer fuses \
         against the wrong thresholds without erroring"
    );

    // And the gate really is a gate: the same perfect judgment with a PASSING fact must
    // score far higher. If these two agree, the gate is inert.
    let passing = hybrid::comparator_core(Comparator::from_i32(spec[0] as i32), 100, 100, spec[1]);
    let unlocked = hybrid::fuse(Fusion::from_i32(spec[2] as i32), passing, 10_000, &k);
    assert_eq!(unlocked, 10_000);
    assert!(unlocked > fused);
}

/// End-to-end through the real export path, on the synthetic model fixture: the comparator
/// and fusion run over a genuine interpreter judgment rather than a hand-fed one.
#[test]
fn score_hybrid_bytes_runs_end_to_end() {
    let dir = concat!(env!("CARGO_MANIFEST_DIR"), "/tests");
    let bytes = std::fs::read(format!("{dir}/model_fixture.imwq"))
        .expect("model_fixture.imwq missing — run gen_model_fixture.py");
    let meta = std::fs::read_to_string(format!("{dir}/model_fixture.txt")).unwrap();
    let mut lines = meta.lines();
    let tokens: Vec<i64> = lines.next().unwrap().split(',').map(|s| s.parse().unwrap()).collect();
    let raw: i64 = lines.next().unwrap().trim().parse().unwrap();

    let spec = wide_wasm::HybridSpec {
        comparator: Comparator::AbsTol,
        tolerance: 50,
        fusion: Fusion::Gate,
        fusion_const: FusionConst {
            pass: 8_000, low: 2_000, floor: 3_000, span: 7_000, w_c: 0, w_j: 0,
        },
    };

    // A correct fact unlocks the gate, so the result is floor + span*judgment/SCORE_ONE and
    // must equal what the golden computes from the SAME raw code the forward-pass test pins.
    let got = wide_wasm::score_hybrid_bytes(&bytes, &tokens, 100, 100, &spec).unwrap();
    let judgment = wide_wasm::judgment_to_score_domain(raw);
    let want = hybrid::fuse(Fusion::Gate, hybrid::SCORE_ONE, judgment, &spec.fusion_const);
    assert_eq!(got, want, "the hybrid path disagreed with comparator_core + fuse composed by hand");

    // A wrong fact must gate it shut, and hard — not shade it slightly.
    let wrong = wide_wasm::score_hybrid_bytes(&bytes, &tokens, 100, 100_000, &spec).unwrap();
    assert_eq!(wrong, 0, "a wildly wrong fact was not gated shut");
    assert!(wrong < got);

    // Determinism: the same inputs twice must give the IDENTICAL integer.
    let again = wide_wasm::score_hybrid_bytes(&bytes, &tokens, 100, 100, &spec).unwrap();
    assert_eq!(got, again, "the hybrid path is not deterministic");

    // Fail closed on the two rejections the export can hit.
    assert!(wide_wasm::score_hybrid_bytes(&bytes, &[], 100, 100, &spec).is_err());
    assert!(wide_wasm::score_hybrid_bytes(b"NOT AN IMWQ FILE", &tokens, 100, 100, &spec).is_err());
}
